const firstName = $('Insert Lead').item.json.first_name;
const serviceType = $('Parse Extracted Data').item.json.extracted.service_type;
const link = $('Build Booking Link').item.json.bookingLink;

const reminderMessage = `Hi ${firstName}, just following up on your ${serviceType} request! Ready to book? Grab a time here: ${link} Reply STOP to opt out.`;

return {
  json: {
    ...$input.item.json,
    reminderMessage
  }
};

const exceptions = $input.all().map(item => item.json);

const lines = exceptions.map(e =>
  `• ${e.exception_type} (${e.minutes_open} min open) — lead_id: ${e.lead_id || 'none'}`
);

// We use a JavaScript template literal to preserve real line breaks
return [
  {
    json: { 
      summary: `🚨 ${exceptions.length} exception(s) need attention:

${lines.join('\n')}` 
    }
  }
];
